namespace Aegis.Studio.Domain.Galleries;
public sealed class MediaActivity{private MediaActivity(){} public MediaActivity(Guid mediaAssetId,string userId,string action,string detail){Id=Guid.NewGuid();MediaAssetId=mediaAssetId;UserId=userId.Trim();Action=action.Trim();Detail=detail.Trim();CreatedUtc=DateTimeOffset.UtcNow;} public Guid Id{get;private set;} public Guid MediaAssetId{get;private set;} public string UserId{get;private set;}=string.Empty; public string Action{get;private set;}=string.Empty; public string Detail{get;private set;}=string.Empty; public DateTimeOffset CreatedUtc{get;private set;}}
